# CDT Workflow Engine - self-extracting source bundle (PowerShell)
# Usage:  .\cdt-src-bundle.ps1
#         .\cdt-src-bundle.ps1 -TargetDir "C:\my-project"
param(
    [string]$TargetDir = "cdt-workflow-src"
)

function Decode-File {
    param([string]$RelPath, [string]$B64Content)
    $dest = Join-Path $TargetDir $RelPath
    $dir  = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [Convert]::FromBase64String($B64Content)
    [System.IO.File]::WriteAllBytes($dest, $bytes)
}

